def build_telemetry_data(telemetry: bool=True, command: Optional[str]=None,
    subcommand: Optional[str]=None) ->TelemetryModel:
    """
    Build telemetry data for Safety.

    Args:
        telemetry (bool): Whether telemetry is enabled.
        command (Optional[str]): The command being executed.
        subcommand (Optional[str]): The subcommand being executed.

    Returns:
        TelemetryModel: The telemetry data model.
    """
    if not telemetry:
        return TelemetryModel()

    try:
        git_data = build_git_data()
    except Exception:
        git_data = {}

    try:
        python_version = f"{sys.version_info.major}.{sys.version_info.minor}.{sys.version_info.micro}"
    except Exception:
        python_version = ""

    try:
        os_type = platform.system()
        os_release = platform.release()
    except Exception:
        os_type = ""
        os_release = ""

    try:
        safety_version = get_safety_version()
    except Exception:
        safety_version = ""

    telemetry_data = TelemetryModel(
        telemetry_enabled=telemetry,
        command=command,
        subcommand=subcommand,
        python_version=python_version,
        os_type=os_type,
        os_release=os_release,
        safety_version=safety_version,
        git_data=git_data
    )

    return telemetry_data

